  <div style={{display:'grid',gridTemplateColumns:'repeat(4,1fr)',gap:10,marginBottom:14}}><div className="card" style={{padding:14,textAlign:'center'}}><Boxes size={18}/><div><b>{summary.types?.size||0}</b><br/><small>Tovar turlari</small></div></div><div className="card" style={{padding:14,textAlign:'center'}}><Warehouse size={18}/><div><b>{summary.on}</b><br/><small>Mavjud</small></div></div><div className="card" style={{padding:14,textAlign:'center'}}><Boxes size={18}/><div><b>{formatMoney(summary.value)}</b><br/><small>Sotish narxi</small></div></div><div className="card" style={{padding:14,textAlign:'center'}}><Warehouse size={18}/><div><b>{formatMoney(summary.cost)}</b><br/><small>Tannarxi</small></div></div></div>
