  const locations=[...new Set(units.map(u=>u.locations?.name).filter(Boolean))];const filteredUnits=filterLocation?units.filter(u=>u.locations?.name===filterLocation):units;const locationSummary=locations.map(n=>({name:n,count:units.filter(u=>u.locations?.name===n).length,type:units.find(u=>u.locations?.name===n)?.locations?.type}));
